<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$ini=$mes.'-01';$fin=date('Y-m-t',strtotime($ini));$p=$pdo->prepare('SELECT COALESCE(SUM(monto),0) FROM pagos WHERE fecha BETWEEN ? AND ?');$p->execute([$ini,$fin]);$ing=(float)$p->fetchColumn();$g=$pdo->prepare('SELECT COALESCE(SUM(monto),0) FROM gastos WHERE fecha BETWEEN ? AND ?');$g->execute([$ini,$fin]);$gas=(float)$g->fetchColumn();$cr=$pdo->prepare('SELECT COALESCE(SUM(monto),0) FROM costos_reales WHERE fecha BETWEEN ? AND ?');$cr->execute([$ini,$fin]);$cost=(float)$cr->fetchColumn();$c=$pdo->prepare('SELECT COALESCE(SUM(total),0) FROM compras WHERE fecha BETWEEN ? AND ? AND estatus<>\'Cancelado\'');$c->execute([$ini,$fin]);$compr=(float)$c->fetchColumn();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finanzas · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('finanzas');?><main class="w"><div class="srnu-page-heading"><div><h1>Finanzas</h1><p>Ingresos, gastos, caja y costos reales.</p></div></div><form class="toolbar"><input type="month" name="mes" value="<?=eh($mes)?>"><button class="btn">Ver mes</button></form><div class="kpi-grid" style="margin-top:16px"><div class="kpi"><small>Cobrado</small><strong><?=emoney($ing)?></strong></div><div class="kpi"><small>Gastos operativos</small><strong><?=emoney($gas)?></strong></div><div class="kpi"><small>Costos reales por trabajos</small><strong><?=emoney($cost)?></strong></div><div class="kpi"><small>Flujo neto simple</small><strong><?=emoney($ing-$gas-$cost)?></strong></div></div><div class="grid-3" style="margin-top:16px"><a class="panel" style="padding:20px;text-decoration:none;color:inherit" href="gastos.php"><h2>Gastos</h2><p class="muted">Renta, servicios, nómina, materiales y otros egresos.</p></a><a class="panel" style="padding:20px;text-decoration:none;color:inherit" href="caja.php"><h2>Cierre de caja</h2><p class="muted">Conciliación diaria por método de pago.</p></a><a class="panel" style="padding:20px;text-decoration:none;color:inherit" href="compras.php"><h2>Compras</h2><p class="muted">Pedidos del mes: <?=emoney($compr)?></p></a></div><section class="panel" style="padding:18px;margin-top:16px"><h3>Reparto por cotización</h3><p class="muted">Desde Cotizaciones → Reparto puedes revisar cuánto le corresponde y cuánto falta por recibir a cada integrante.</p><a class="btn blue" href="cotizaciones.php">Ir a cotizaciones</a></section></main></body></html>
